solution.Solution.cs:
public static class Solution
{
    public static (int Min, int Max, double Mean) Stats(params int[] values)
    {
        if (values.Length == 0) throw new ArgumentException("no values", nameof(values));
        int min = values[0], max = values[0];
        long sum = 0;
        foreach (int v in values)
        {
            if (v < min) min = v;
            if (v > max) max = v;
            sum += v;
        }
        return (min, max, (double)sum / values.Length);
    }

    public static bool TryParseTime(string text, out int minutes)
    {
        minutes = 0;
        string[] parts = text.Split(':');
        if (parts.Length != 2 || parts[0].Length is < 1 or > 2 || parts[1].Length != 2) return false;
        if (!int.TryParse(parts[0], out int h) || !int.TryParse(parts[1], out int m)) return false;
        if (parts[0].Any(c => !char.IsDigit(c)) || parts[1].Any(c => !char.IsDigit(c))) return false;
        if (h > 23 || m > 59) return false;
        minutes = h * 60 + m;
        return true;
    }

    public static string Repeat(string text, int times, string separator = "")
    {
        var sb = new StringBuilder();
        for (int i = 0; i < times; i++)
        {
            if (i > 0) sb.Append(separator);
            sb.Append(text);
        }
        return sb.ToString();
    }

    public static long Power(long baseValue, int exponent)
    {
        if (exponent == 0) return 1;
        long half = Power(baseValue, exponent / 2);
        return exponent % 2 == 0 ? half * half : half * half * baseValue;
    }
}

unitTests:
Test("stats as a tuple", () =>
{
    var (min, max, mean) = Stats(4, 9, 1, 6);
    CheckEq(min, 1);
    CheckEq(max, 9);
    CheckNear(mean, 5);
    CheckEq(Stats(7).Max, 7);
    CheckNear(Stats(int.MaxValue, int.MaxValue).Mean, int.MaxValue);
    CheckThrows<ArgumentException>(() => Stats());
});

Test("parsing times", () =>
{
    CheckEq(TryParseTime("9:05", out int a), true);
    CheckEq(a, 545);
    CheckEq(TryParseTime("23:59", out int b) && b == 1439, true);
    CheckEq(TryParseTime("00:00", out int c) && c == 0, true);
    foreach (string bad in new[] { "24:00", "9:60", "9:5", "abc", "1:2:3", "", "-1:30", "+1:30", "123:00" })
    {
        bool ok = TryParseTime(bad, out int m);
        Check(!ok && m == 0, $"\"{bad}\" should not parse");
    }
});

Test("repeat with optional separator", () =>
{
    CheckEq(Repeat("ab", 3, "-"), "ab-ab-ab");
    CheckEq(Repeat("x", 4), "xxxx");
    CheckEq(Repeat("x", 0, ","), "");
    CheckEq(Repeat("hi", 2, separator: ", "), "hi, hi");
});

Test("fast power", () =>
{
    CheckEq(Power(2, 10), 1024L);
    CheckEq(Power(3, 0), 1L);
    CheckEq(Power(-2, 3), -8L);
    CheckEq(Power(10, 18), 1_000_000_000_000_000_000L);
});

